<template><div v-if="event" class="demo-widget tts-widget" :style="widgetStyle(widget.settings)"><div v-if="widget.settings.showAvatar" class="avatar">🔊</div><div><span v-if="widget.settings.showStatus" class="widget-kicker">{{ event.payload?.status || (runtimeMode === 'browser-source' ? 'READY' : 'SIMULATED · READY') }}</span><b v-if="widget.settings.showSpeaker">{{ event.actor?.displayName }}</b><p>{{ event.payload?.text }}</p></div></div></template>
<script setup>import { watch } from 'vue'; import { widgetStyle,useWidgetEvents } from '../../widgetHelpers.js'; const props=defineProps({widget:{type:Object,required:true},runtimeMode:{type:String,default:'editor-preview'}}); const event=useWidgetEvents(props.widget,props.runtimeMode==='browser-source'?null:{actor:{displayName:'VoiceTester'},payload:{text:'Visual preview only — speech playback is not connected.',status:'SIMULATED'}}); watch(event,(next)=>{const text=String(next?.payload?.text||'').trim();if(props.runtimeMode!=='browser-source'||!text||!('speechSynthesis' in window))return;window.speechSynthesis.cancel();window.speechSynthesis.speak(new SpeechSynthesisUtterance(text))})</script>
